const BUNDLE_ID = "eye-of-vengeance-v1";
const ITEM_NAME = "Око Возмездия v1.0";
const JOURNAL_NAME = "Памятка: Око Возмездия v1.0";
const FOLDER_NAME = "Артефакты AI Patcher";
const IMG_PATH = "assets/eye-of-vengeance.png";
let IMG = "icons/magic/perception/eye-ringed-glow-angry-red.webp";
const FLAG_SCOPE = "world";
const FLAG_WEAPON_UUID = "eyeOfVengeanceWeaponUuid";
const FLAG_WEAPON_NAME = "eyeOfVengeanceWeaponName";
const FLAG_ABILITY = "eyeOfVengeanceAbility";
const FLAG_USES = "eyeOfVengeanceUsesSinceRest";
const FLAG_LAST_TURN = "eyeOfVengeanceLastTurn";

function asset(bundle, localPath) {
  return bundle?.assets?.[localPath] ?? "modules/ai-patcher/inbox/" + BUNDLE_ID + "/" + localPath;
}

function clone(data) {
  return foundry.utils.deepClone(data);
}

function activityValues(activities) {
  if (!activities) return [];
  if (activities.contents) return activities.contents;
  if (activities.values) return Array.from(activities.values());
  return Object.values(activities);
}

async function getOrCreateFolder(name, type) {
  const existing = game.folders.find(function(folder) { return folder.type === type && folder.name === name; });
  if (existing) return existing;
  return Folder.create({ name: name, type: type });
}

function itemAutomationFlags(command) {
  const autoName = ITEM_NAME + " Автодействие";
  return {
    itemacro: {
      macro: {
        name: autoName,
        type: "script",
        img: IMG,
        scope: "global",
        command: command,
        author: game.user.id,
        ownership: { default: 0, [game.user.id]: 3 }
      }
    },
    "midi-qol": {
      onUseMacroName: autoName + ",[postActiveEffects]ItemMacro"
    }
  };
}

function htmlDescription() {
  return [
    '<div class="ai-patcher-item-description">',
    '<p><em>Багровый самоцвет в серебряной оправе. При настройке он срастается со лбом владельца, оставляя тонкий вертикальный шрам. Во время использования силы артефакта шрам раскрывается, превращаясь в сияющий алый третий глаз, а собственные глаза владельца непроизвольно закрываются.</em></p>',
    '<h3>Артефакт</h3>',
    '<p><strong>Чудесный предмет, артефакт, требует настройки</strong></p>',
    '<h3>Нерушимая связь</h3>',
    '<p>После настройки артефакт невозможно добровольно снять или передать другому существу. Пока владелец жив, Око нельзя извлечь из его тела или настроить на другое существо. Связь прекращается только после окончательной смерти владельца. Разорвать её способны лишь <strong>Исполнение желаний</strong> или прямое вмешательство божества. После смерти владельца артефакт сам найдёт нового достойного владельца.</p>',
    '<h3>Избранное оружие</h3>',
    '<p>Во время настройки выбери один экземпляр оружия ближнего боя. Пока ты настроен на Око, ты считаешься владеющим выбранным оружием, можешь использовать выбранную заклинательную характеристику вместо Силы или Ловкости для бросков атаки и урона этим оружием, а выбранное оружие считается магическим. Если выбранное оружие уничтожено, после продолжительного отдыха ты можешь связать Око с другим оружием ближнего боя.</p>',
    '<h3>Месть Самиэля</h3>',
    '<p><strong>Действие.</strong> Самиэль не карает невиновных. Способность может быть использована только против существа, которое, по решению Мастера, действительно заслуживает суда.</p>',
    '<p>Выбери видимое существо в пределах <strong>100 футов</strong>. Ты телепортируешься в свободное пространство, из которого способен совершить атаку по выбранной цели, после чего совершаешь одну и только одну атаку ближнего боя. Если подходящего свободного пространства не существует, способность не расходуется.</p>',
    '<p>Пока открыт третий глаз, ты считаешься <strong>ослеплённым</strong>, однако это состояние не мешает использованию Мести Самиэля.</p>',
    '<p>Эта атака автоматически попадает, считается критическим попаданием, а все кубы урона считаются выпавшими с максимальным результатом. Если при обычной атаке этим оружием по выбранной цели ты не совершал бы бросок атаки с помехой, а цель не находится под эффектом действия «Отход», атака дополнительно наносит <strong>19 урона</strong>.</p>',
    '<h3>Неотвратимый приговор</h3>',
    '<p>Весь урон, наносимый Местью Самиэля, является неотвратимым. Он игнорирует сопротивления и иммунитеты и не может быть уменьшен, предотвращён, отменён, перенаправлен, разделён между несколькими существами или заменён потерей иного ресурса. Временные хиты поглощают этот урон как обычно. Месть Самиэля никогда не совершается дважды в одном ходу.</p>',
    '<p>После применения твой ход немедленно заканчивается; действие, бонусное действие, взаимодействие с предметом и реакция считаются израсходованными. Если хотя бы один из этих ресурсов уже был израсходован, способность использовать нельзя.</p>',
    '<h3>Стойка мученика</h3>',
    '<p>До начала своего следующего хода ты получаешь <strong>+3 к КД</strong>, <strong>+3 ко всем спасброскам</strong> и уязвимость к дробящему, колющему и рубящему урону, включая магический.</p>',
    '<h3>Цена возмездия</h3>',
    '<p>Первое применение Мести Самиэля после продолжительного отдыха не имеет дополнительных последствий. Каждое последующее применение до окончания следующего продолжительного отдыха накладывает <strong>2 уровня Истощения</strong>. Это Истощение нельзя предотвратить, уменьшить или перенаправить. Оно снимается по обычным правилам.</p>',
    '</div>'
  ].join('\n');
}

function chatDescription() {
  return "Артефакт с неразрывной настройкой: выбери оружие ближнего боя, затем используй Месть Самиэля для неотвратимого максимального критического удара по достойной суда цели.";
}

const EYE_AUTOMATION = "(" + (async function eyeOfVengeanceAutomation() {
  const BUNDLE_ID = "eye-of-vengeance-v1";
  const FLAG_SCOPE = "world";
  const FLAG_WEAPON_UUID = "eyeOfVengeanceWeaponUuid";
  const FLAG_ABILITY = "eyeOfVengeanceAbility";
  const FLAG_USES = "eyeOfVengeanceUsesSinceRest";
  const FLAG_LAST_TURN = "eyeOfVengeanceLastTurn";
  const data = args?.[0] ?? {};
  const pass = data.macroPass ?? "postActiveEffects";
  const sourceItem = item ?? data.workflow?.item;
  const selfActor = actor ?? data.workflow?.actor ?? sourceItem?.parent;
  if (pass !== "postActiveEffects" || !sourceItem) return;

  function activityName() {
    return String(data.workflow?.activity?.name ?? data.activity?.name ?? "");
  }

  function escapeHtml(value) {
    return String(value ?? "").replace(/[&<>\"]/g, function(ch) {
      return ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;" })[ch];
    });
  }

  function actorItems(actor) {
    if (!actor?.items) return [];
    if (actor.items.contents) return actor.items.contents;
    if (actor.items.values) return Array.from(actor.items.values());
    return Array.from(actor.items);
  }

  function actorEffects(actor) {
    if (!actor?.effects) return [];
    if (actor.effects.contents) return actor.effects.contents;
    if (actor.effects.values) return Array.from(actor.effects.values());
    return Array.from(actor.effects);
  }

  function dialogResult(config) {
    return new Promise(function(resolve) {
      let done = false;
      function finish(value) {
        if (done) return;
        done = true;
        resolve(value);
      }
      new Dialog({
        title: config.title,
        content: config.content,
        buttons: config.buttons(finish),
        default: config.default ?? "ok",
        close: function() { finish(null); }
      }).render(true);
    });
  }

  function abilityLabel(ability) {
    return ({ int: "Интеллект", wis: "Мудрость", cha: "Харизма" })[ability] ?? ability;
  }

  function abilityMod(actor, ability) {
    return Number(actor?.system?.abilities?.[ability]?.mod ?? 0);
  }

  function profBonus(actor) {
    return Number(actor?.system?.attributes?.prof ?? actor?.system?.prof ?? 0);
  }

  function sourceToken() {
    const macroToken = typeof token !== "undefined" ? token : null;
    return macroToken ?? data.workflow?.token ?? canvas.tokens?.controlled?.find(function(t) { return t.actor?.id === selfActor?.id; }) ?? canvas.tokens?.placeables?.find(function(t) { return t.actor?.id === selfActor?.id; });
  }

  function tokenDistance(a, b) {
    if (!a || !b) return Infinity;
    if (canvas.grid?.measurePath) return Number(canvas.grid.measurePath([a.center, b.center])?.distance ?? Infinity);
    const gridSize = canvas.grid?.size || 100;
    const gridDistance = canvas.scene?.grid?.distance || 5;
    return Math.hypot(a.center.x - b.center.x, a.center.y - b.center.y) / gridSize * gridDistance;
  }

  function meleeWeapons(actor) {
    return actorItems(actor).filter(function(candidate) {
      if (candidate.type !== "weapon") return false;
      const actionType = String(candidate.system?.actionType ?? "");
      const weaponType = String(candidate.system?.type?.value ?? candidate.system?.type ?? "");
      const rangeUnits = String(candidate.system?.range?.units ?? "");
      if (/rwak|rsak/i.test(actionType)) return false;
      if (/simpleR|martialR|ranged/i.test(weaponType)) return false;
      if (/ft|м|фут/i.test(rangeUnits) && Number(candidate.system?.range?.value ?? 0) > 15 && !Number(candidate.system?.range?.reach ?? 0)) return false;
      return true;
    });
  }

  function weaponByUuidOrId(actor, uuid) {
    const items = actorItems(actor);
    return items.find(function(candidate) { return candidate.uuid === uuid || candidate.id === uuid; }) ?? null;
  }

  function firstDamagePart(part) {
    if (!part) return "";
    if (Array.isArray(part)) return String(part[0] ?? "");
    if (typeof part === "string") return part;
    if (part.formula) return String(part.formula);
    const number = Number(part.number ?? 0);
    const denomination = Number(part.denomination ?? 0);
    const bonus = String(part.bonus ?? "").trim();
    if (number > 0 && denomination > 0) return String(number) + "d" + String(denomination) + (bonus ? " + " + bonus : "");
    if (part.custom?.formula) return String(part.custom.formula);
    return "";
  }

  function weaponDamageFormula(weapon) {
    const parts = [];
    const oldParts = weapon?.system?.damage?.parts;
    if (Array.isArray(oldParts)) {
      for (const part of oldParts) {
        const formula = firstDamagePart(part);
        if (formula) parts.push(formula);
      }
    }
    const activities = weapon?.system?.activities;
    const activityList = activities?.contents ? activities.contents : activities?.values ? Array.from(activities.values()) : Object.values(activities ?? {});
    for (const activity of activityList) {
      const damageParts = activity?.damage?.parts;
      if (!Array.isArray(damageParts)) continue;
      for (const part of damageParts) {
        const formula = firstDamagePart(part);
        if (formula) parts.push(formula);
      }
    }
    const unique = Array.from(new Set(parts.filter(Boolean)));
    if (unique.length) return unique.join(" + ");
    return "1d8 + @mod";
  }

  function weaponReach(weapon) {
    const reach = Number(weapon?.system?.range?.reach ?? 0);
    if (reach > 0) return reach;
    const value = Number(weapon?.system?.range?.value ?? 0);
    if (value > 0 && value <= 15) return value;
    return 5;
  }

  function selectedWeapon(actor) {
    const uuid = sourceItem.getFlag(FLAG_SCOPE, FLAG_WEAPON_UUID);
    return uuid ? weaponByUuidOrId(actor, uuid) : null;
  }

  async function configureEye() {
    if (!selfActor) {
      ui.notifications?.warn("Перенесите Око Возмездия на лист персонажа и запускайте настройку оттуда.");
      return;
    }
    const weapons = meleeWeapons(selfActor);
    if (!weapons.length) {
      ui.notifications?.warn("У персонажа не найдено оружие ближнего боя.");
      return;
    }
    const currentUuid = sourceItem.getFlag(FLAG_SCOPE, FLAG_WEAPON_UUID) ?? "";
    const currentAbility = sourceItem.getFlag(FLAG_SCOPE, FLAG_ABILITY) ?? selfActor.system?.attributes?.spellcasting ?? "cha";
    const weaponOptions = weapons.map(function(weapon) {
      const selected = weapon.uuid === currentUuid || weapon.id === currentUuid ? "selected" : "";
      return '<option value="' + escapeHtml(weapon.uuid ?? weapon.id) + '" ' + selected + '>' + escapeHtml(weapon.name) + '</option>';
    }).join("");
    const abilityOptions = ["cha", "wis", "int"].map(function(ability) {
      const selected = ability === currentAbility ? "selected" : "";
      return '<option value="' + ability + '" ' + selected + '>' + abilityLabel(ability) + '</option>';
    }).join("");
    const spent = Number(sourceItem.system?.uses?.spent ?? sourceItem.getFlag(FLAG_SCOPE, FLAG_USES) ?? 0);
    const result = await dialogResult({
      title: "Настроить Око Возмездия",
      content: [
        '<form class="eye-of-vengeance-config">',
        '<p>Выберите оружие ближнего боя и заклинательную характеристику. Око запомнит выбор на этом персонаже.</p>',
        '<div class="form-group"><label>Избранное оружие</label><select name="weapon">' + weaponOptions + '</select></div>',
        '<div class="form-group"><label>Характеристика</label><select name="ability">' + abilityOptions + '</select></div>',
        '<label style="display:flex; gap:8px; align-items:flex-start; margin-top:8px;"><input type="checkbox" name="resetUses"><span>Сбросить счётчик Мести после продолжительного отдыха. Сейчас применений: <strong>' + spent + '</strong>.</span></label>',
        '<p><small>Если выбранное оружие существует на листе, Око пометит его как магическое и попробует перевести атаки на выбранную характеристику.</small></p>',
        '</form>'
      ].join(""),
      default: "save",
      buttons: function(finish) {
        return {
          save: {
            icon: '<i class="fas fa-eye"></i>',
            label: "Сохранить",
            callback: async function(html) {
              const root = html[0] ?? html;
              finish({
                weapon: root.querySelector('[name="weapon"]')?.value ?? "",
                ability: root.querySelector('[name="ability"]')?.value ?? "cha",
                resetUses: !!root.querySelector('[name="resetUses"]')?.checked
              });
            }
          },
          cancel: { label: "Отмена", callback: function() { finish(null); } }
        };
      }
    });
    if (!result) return;
    const weapon = weaponByUuidOrId(selfActor, result.weapon);
    if (!weapon) {
      ui.notifications?.warn("Выбранное оружие не найдено на листе персонажа.");
      return;
    }
    const props = Array.from(weapon.system?.properties ?? []);
    const weaponUpdate = {};
    if (!props.includes("mgc")) weaponUpdate["system.properties"] = props.concat(["mgc"]);
    if (foundry.utils.hasProperty(weapon, "system.ability")) weaponUpdate["system.ability"] = result.ability;
    if (foundry.utils.hasProperty(weapon, "system.proficient")) weaponUpdate["system.proficient"] = 1;
    if (Object.keys(weaponUpdate).length) await weapon.update(weaponUpdate);
    await sourceItem.setFlag(FLAG_SCOPE, FLAG_WEAPON_UUID, weapon.uuid ?? weapon.id);
    await sourceItem.setFlag(FLAG_SCOPE, "eyeOfVengeanceWeaponName", weapon.name);
    await sourceItem.setFlag(FLAG_SCOPE, FLAG_ABILITY, result.ability);
    const itemUpdate = { "system.attuned": true, "system.equipped": true };
    if (result.resetUses) {
      itemUpdate["system.uses.spent"] = 0;
      await sourceItem.setFlag(FLAG_SCOPE, FLAG_USES, 0);
    }
    await sourceItem.update(itemUpdate);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: selfActor }),
      content: '<p><strong>Око Возмездия настроено.</strong> Избранное оружие: <strong>' + escapeHtml(weapon.name) + '</strong>. Характеристика: <strong>' + abilityLabel(result.ability) + '</strong>.</p>'
    });
  }

  function candidateTargets(source, range) {
    return (canvas.tokens?.placeables ?? []).filter(function(candidate) {
      if (!candidate.actor || candidate.id === source?.id || candidate.document?.hidden) return false;
      if (Number(candidate.actor.system?.attributes?.hp?.value ?? 1) <= 0) return false;
      return tokenDistance(source, candidate) <= range;
    });
  }

  async function chooseTarget(source, range) {
    const targeted = Array.from(game.user?.targets ?? []).filter(function(target) { return target.actor; });
    if (targeted.length === 1) return targeted[0];
    if (targeted.length > 1) {
      ui.notifications?.warn("Для Мести Самиэля выберите только одну цель.");
      return null;
    }
    const candidates = candidateTargets(source, range);
    if (!candidates.length) return null;
    const options = candidates.map(function(candidate) {
      return '<option value="' + candidate.id + '">' + escapeHtml(candidate.name) + ' — ' + Math.round(tokenDistance(source, candidate)) + ' фт</option>';
    }).join("");
    const result = await dialogResult({
      title: "Цель Мести Самиэля",
      content: '<form><p>Выберите видимую цель в пределах 100 футов.</p><div class="form-group"><label>Цель</label><select name="target">' + options + '</select></div></form>',
      default: "ok",
      buttons: function(finish) {
        return {
          ok: { icon: '<i class="fas fa-crosshairs"></i>', label: "Выбрать", callback: function(html) { const root = html[0] ?? html; finish(root.querySelector('[name="target"]')?.value ?? ""); } },
          cancel: { label: "Отмена", callback: function() { finish(null); } }
        };
      }
    });
    if (!result) return null;
    return canvas.tokens?.get?.(result) ?? candidates.find(function(candidate) { return candidate.id === result; }) ?? null;
  }

  function occupiedByOther(x, y, width, height, sourceId, targetId) {
    return (canvas.tokens?.placeables ?? []).some(function(other) {
      if (!other.actor || other.id === sourceId || other.id === targetId || other.document?.hidden) return false;
      const ow = Number(other.document?.width ?? 1) * (canvas.grid?.size || 100);
      const oh = Number(other.document?.height ?? 1) * (canvas.grid?.size || 100);
      const ox = Number(other.document?.x ?? other.x ?? 0);
      const oy = Number(other.document?.y ?? other.y ?? 0);
      return x < ox + ow && x + width > ox && y < oy + oh && y + height > oy;
    });
  }

  function findTeleportSpot(source, target, reach) {
    if (!canvas?.grid || !canvas?.scene || !source?.document || !target?.document) return null;
    const gridSize = canvas.grid.size || 100;
    const gridDistance = canvas.scene.grid?.distance || 5;
    const sourceWidth = Number(source.document.width ?? 1) * gridSize;
    const sourceHeight = Number(source.document.height ?? 1) * gridSize;
    const targetX = Number(target.document.x ?? target.x ?? 0);
    const targetY = Number(target.document.y ?? target.y ?? 0);
    const rings = Math.max(2, Math.ceil((reach + gridDistance) / gridDistance) + 3);
    const candidates = [];
    for (let dx = -rings; dx <= rings; dx++) {
      for (let dy = -rings; dy <= rings; dy++) {
        const x = targetX + dx * gridSize;
        const y = targetY + dy * gridSize;
        if (x < 0 || y < 0 || x + sourceWidth > canvas.scene.dimensions.width || y + sourceHeight > canvas.scene.dimensions.height) continue;
        if (occupiedByOther(x, y, sourceWidth, sourceHeight, source.id, target.id)) continue;
        const center = { x: x + sourceWidth / 2, y: y + sourceHeight / 2 };
        const distToTarget = Math.hypot(center.x - target.center.x, center.y - target.center.y) / gridSize * gridDistance;
        if (distToTarget > reach || distToTarget < 0.1) continue;
        const distFromSource = Math.hypot(center.x - source.center.x, center.y - source.center.y);
        candidates.push({ x: x, y: y, score: distFromSource });
      }
    }
    candidates.sort(function(a, b) { return a.score - b.score; });
    return candidates[0] ?? null;
  }

  async function teleportNearTarget(source, target, reach) {
    const spot = findTeleportSpot(source, target, reach);
    if (!spot) return false;
    const update = { x: spot.x, y: spot.y };
    if (foundry.utils.hasProperty(target.document, "elevation")) update.elevation = target.document.elevation ?? source.document.elevation ?? 0;
    await source.document.update(update);
    return true;
  }

  async function confirmVengeance(target, weapon, baseFormula, uses) {
    return dialogResult({
      title: "Месть Самиэля",
      content: [
        '<form class="eye-of-vengeance-vengeance">',
        '<p><strong>Цель:</strong> ' + escapeHtml(target.name) + '<br><strong>Оружие:</strong> ' + escapeHtml(weapon.name) + '</p>',
        '<label style="display:flex; gap:8px; align-items:flex-start; margin:6px 0;"><input type="checkbox" name="judged"><span>Мастер подтверждает: цель действительно заслуживает суда.</span></label>',
        '<label style="display:flex; gap:8px; align-items:flex-start; margin:6px 0;"><input type="checkbox" name="resources"><span>Действие, бонусное действие, взаимодействие с предметом и реакция ещё не были потрачены в этот ход.</span></label>',
        '<label style="display:flex; gap:8px; align-items:flex-start; margin:6px 0;"><input type="checkbox" name="bonus19" checked><span>Нет помехи при обычной атаке, и цель не под действием «Отход»: добавить 19 урона.</span></label>',
        '<label style="display:flex; gap:8px; align-items:flex-start; margin:6px 0;"><input type="checkbox" name="teleport" checked><span>Телепортировать владельца к цели перед ударом.</span></label>',
        '<label style="display:flex; gap:8px; align-items:flex-start; margin:6px 0;"><input type="checkbox" name="endTurn" checked><span>Если сейчас ход владельца, закончить его после удара.</span></label>',
        '<div class="form-group"><label>Основная формула урона выбранного оружия</label><input type="text" name="baseFormula" value="' + escapeHtml(baseFormula) + '"></div>',
        '<div class="form-group"><label>Дополнительные кубы или бонусы, которые входят в эту атаку</label><input type="text" name="extraFormula" placeholder="например: 2d8 + 3d6"></div>',
        '<p><small>Все кубы будут посчитаны как максимальные на критическом попадании. Урон будет снят напрямую с временных хитов, затем с хитов, игнорируя сопротивления и иммунитеты.</small></p>',
        '<p><small>Применений после отдыха: <strong>' + uses + '</strong>. Если это не первое применение, владелец получит 2 уровня Истощения.</small></p>',
        '</form>'
      ].join(""),
      default: "ok",
      buttons: function(finish) {
        return {
          ok: {
            icon: '<i class="fas fa-gavel"></i>',
            label: "Исполнить приговор",
            callback: function(html) {
              const root = html[0] ?? html;
              finish({
                judged: !!root.querySelector('[name="judged"]')?.checked,
                resources: !!root.querySelector('[name="resources"]')?.checked,
                bonus19: !!root.querySelector('[name="bonus19"]')?.checked,
                teleport: !!root.querySelector('[name="teleport"]')?.checked,
                endTurn: !!root.querySelector('[name="endTurn"]')?.checked,
                baseFormula: root.querySelector('[name="baseFormula"]')?.value ?? "",
                extraFormula: root.querySelector('[name="extraFormula"]')?.value ?? ""
              });
            }
          },
          cancel: { label: "Отмена", callback: function() { finish(null); } }
        };
      }
    });
  }

  async function maximumFormula(formula, actor, ability) {
    const clean = String(formula ?? "").trim();
    if (!clean) return { total: 0, formula: "", maxed: "0" };
    const rollData = actor?.getRollData ? actor.getRollData() : {};
    rollData.mod = abilityMod(actor, ability);
    rollData.prof = profBonus(actor);
    let replaced = clean;
    try {
      replaced = Roll.replaceFormulaData(clean, rollData, { missing: "0" });
    } catch (error) {
      replaced = clean.replace(/@mod/g, String(rollData.mod)).replace(/@prof/g, String(rollData.prof));
    }
    replaced = replaced.replace(/@mod/g, String(rollData.mod)).replace(/@prof/g, String(rollData.prof));
    const maxed = replaced.replace(/(\d*)d(\d+)/gi, function(match, count, die) {
      const n = Number(count || 1);
      const d = Number(die || 0);
      return String(n * d * 2);
    });
    const roll = await new Roll(maxed || "0").evaluate({ async: true });
    return { total: Math.floor(Number(roll.total ?? 0)), formula: replaced, maxed: maxed };
  }

  async function applyUnavoidableDamage(target, amount) {
    const targetActor = target?.actor;
    if (!targetActor) return null;
    const hp = targetActor.system?.attributes?.hp ?? {};
    const current = Number(hp.value ?? 0);
    const temp = Number(hp.temp ?? 0);
    const absorbed = Math.min(temp, amount);
    const remaining = Math.max(0, amount - absorbed);
    const nextTemp = Math.max(0, temp - absorbed);
    const nextHp = Math.max(0, current - remaining);
    await targetActor.update({ "system.attributes.hp.temp": nextTemp, "system.attributes.hp.value": nextHp });
    return { beforeHp: current, beforeTemp: temp, afterHp: nextHp, afterTemp: nextTemp, absorbed: absorbed };
  }

  async function applyEffect(actor, effectData) {
    if (!actor) return;
    const old = actorEffects(actor).filter(function(effect) { return effect.getFlag?.("ai-patcher", effectData.flag); });
    if (old.length) await actor.deleteEmbeddedDocuments("ActiveEffect", old.map(function(effect) { return effect.id; }));
    await actor.createEmbeddedDocuments("ActiveEffect", [{
      name: effectData.name,
      img: sourceItem.img,
      origin: sourceItem.uuid,
      duration: effectData.duration ?? { rounds: 1 },
      statuses: effectData.statuses ?? [],
      changes: effectData.changes ?? [],
      description: effectData.description ?? "",
      flags: {
        "ai-patcher": { bundleId: BUNDLE_ID, [effectData.flag]: true },
        dae: effectData.dae ?? {}
      }
    }]);
  }

  async function applyMartyrStance(actor) {
    await applyEffect(actor, {
      name: "Стойка мученика",
      flag: "eyeOfVengeanceMartyrStance",
      duration: { rounds: 1, turns: 1 },
      changes: [
        { key: "system.attributes.ac.bonus", mode: CONST.ACTIVE_EFFECT_MODES.ADD, value: "3", priority: 20 },
        { key: "system.bonuses.abilities.save", mode: CONST.ACTIVE_EFFECT_MODES.ADD, value: "+3", priority: 20 },
        { key: "system.traits.dv.value", mode: CONST.ACTIVE_EFFECT_MODES.ADD, value: "bludgeoning", priority: 20 },
        { key: "system.traits.dv.value", mode: CONST.ACTIVE_EFFECT_MODES.ADD, value: "piercing", priority: 20 },
        { key: "system.traits.dv.value", mode: CONST.ACTIVE_EFFECT_MODES.ADD, value: "slashing", priority: 20 }
      ],
      dae: { specialDuration: ["turnStartSource"] },
      description: "+3 к КД, +3 ко всем спасброскам; уязвимость к дробящему, колющему и рубящему урону, включая магический, до начала следующего хода."
    });
    await applyEffect(actor, {
      name: "Ход завершён Местью Самиэля",
      flag: "eyeOfVengeanceTurnSpent",
      duration: { rounds: 1, turns: 1 },
      changes: [
        { key: "flags.midi-qol.fail.reaction.all", mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: "1", priority: 20 }
      ],
      dae: { specialDuration: ["turnStartSource"] },
      description: "После Мести Самиэля действие, бонусное действие, взаимодействие с предметом и реакция считаются израсходованными."
    });
  }

  async function addExhaustion(actor, amount) {
    const current = Number(actor?.system?.attributes?.exhaustion ?? 0);
    await actor.update({ "system.attributes.exhaustion": current + amount });
  }

  function currentCombatTurnKey(actor) {
    const combat = game.combat;
    if (!combat) return null;
    return String(combat.id) + ":" + String(combat.round) + ":" + String(combat.turn) + ":" + String(actor?.id ?? "");
  }

  async function endTurnIfCurrent(actor) {
    const combat = game.combat;
    if (!combat) return false;
    const currentActor = combat.combatant?.actor;
    if (!currentActor || currentActor.id !== actor?.id) return false;
    try {
      await combat.nextTurn();
      return true;
    } catch (error) {
      ui.notifications?.warn("Удар выполнен, но ход не удалось завершить автоматически. Завершите ход вручную.");
      return false;
    }
  }

  async function vengeance() {
    if (!selfActor) {
      ui.notifications?.warn("Месть Самиэля нужно запускать с листа владельца Ока.");
      return;
    }
    const source = sourceToken();
    if (!source) {
      ui.notifications?.warn("Не найден токен владельца на сцене.");
      return;
    }
    const combatKey = currentCombatTurnKey(selfActor);
    if (combatKey && sourceItem.getFlag(FLAG_SCOPE, FLAG_LAST_TURN) === combatKey) {
      ui.notifications?.warn("Месть Самиэля уже была использована в этот ход.");
      return;
    }
    const weapon = selectedWeapon(selfActor);
    if (!weapon) {
      ui.notifications?.warn("Сначала используйте «Настроить Око» и выберите оружие ближнего боя.");
      return;
    }
    const target = await chooseTarget(source, 100);
    if (!target) {
      ui.notifications?.warn("Нет подходящей цели в пределах 100 футов.");
      return;
    }
    const distance = tokenDistance(source, target);
    if (distance > 100) {
      ui.notifications?.warn("Цель дальше 100 футов. Способность не расходуется.");
      return;
    }
    const systemSpent = Number(sourceItem.system?.uses?.spent ?? 0);
    const flagUses = Number(sourceItem.getFlag(FLAG_SCOPE, FLAG_USES) ?? 0);
    const uses = systemSpent === 0 ? 0 : Math.max(systemSpent, flagUses);
    const ability = sourceItem.getFlag(FLAG_SCOPE, FLAG_ABILITY) ?? selfActor.system?.attributes?.spellcasting ?? "cha";
    const baseFormula = weaponDamageFormula(weapon);
    const confirmed = await confirmVengeance(target, weapon, baseFormula, uses);
    if (!confirmed) return;
    if (!confirmed.judged) {
      ui.notifications?.warn("Самиэль не карает невиновных: Мастер должен подтвердить, что цель заслуживает суда.");
      return;
    }
    if (!confirmed.resources) {
      ui.notifications?.warn("Месть Самиэля нельзя использовать, если действие, бонусное действие, взаимодействие с предметом или реакция уже были потрачены.");
      return;
    }
    if (confirmed.teleport) {
      const moved = await teleportNearTarget(source, target, weaponReach(weapon));
      if (!moved) {
        ui.notifications?.warn("Не найдено свободное место для телепорта. Способность не расходуется.");
        return;
      }
    }
    const base = await maximumFormula(confirmed.baseFormula, selfActor, ability);
    const extra = await maximumFormula(confirmed.extraFormula, selfActor, ability);
    const bonus = confirmed.bonus19 ? 19 : 0;
    const total = Math.max(0, base.total + extra.total + bonus);
    const damage = await applyUnavoidableDamage(target, total);
    await applyMartyrStance(selfActor);
    if (uses >= 1) await addExhaustion(selfActor, 2);
    const nextUses = uses + 1;
    await sourceItem.setFlag(FLAG_SCOPE, FLAG_USES, nextUses);
    await sourceItem.update({ "system.uses.spent": Math.min(99, nextUses) });
    if (combatKey) await sourceItem.setFlag(FLAG_SCOPE, FLAG_LAST_TURN, combatKey);
    const elevationNote = Number(target.document?.elevation ?? 0) !== Number(source.document?.elevation ?? 0) ? '<p><em>Цель находилась на другой высоте. Если владельца ничто не удерживает в воздухе после атаки, примените падение по обычным правилам.</em></p>' : '';
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: selfActor, token: source.document }),
      content: [
        '<div class="eye-of-vengeance-result">',
        '<h2>Месть Самиэля</h2>',
        '<p><strong>' + escapeHtml(selfActor.name) + '</strong> открывает алый третий глаз и наносит неотвратимый приговор по цели <strong>' + escapeHtml(target.name) + '</strong>.</p>',
        '<p><strong>Авто-попадание. Критическое попадание. Кубы урона максимальны.</strong></p>',
        '<ul>',
        '<li>Оружие: <strong>' + escapeHtml(weapon.name) + '</strong></li>',
        '<li>Основная формула: <code>' + escapeHtml(base.formula || "0") + '</code> → <strong>' + base.total + '</strong></li>',
        extra.formula ? '<li>Дополнительно: <code>' + escapeHtml(extra.formula) + '</code> → <strong>' + extra.total + '</strong></li>' : '',
        bonus ? '<li>Условие без помехи и без «Отхода»: <strong>+19</strong></li>' : '',
        '<li>Итого неотвратимого урона: <strong>' + total + '</strong></li>',
        damage ? '<li>Временные хиты поглотили: <strong>' + damage.absorbed + '</strong>. Хиты цели: <strong>' + damage.beforeHp + '</strong> → <strong>' + damage.afterHp + '</strong>.</li>' : '',
        uses >= 1 ? '<li>Цена возмездия: владелец получает <strong>2 уровня Истощения</strong>.</li>' : '<li>Первое применение после отдыха: без дополнительной цены.</li>',
        '</ul>',
        '<p><strong>Стойка мученика:</strong> +3 к КД, +3 ко всем спасброскам; уязвимость к дробящему, колющему и рубящему урону до начала следующего хода.</p>',
        elevationNote,
        '</div>'
      ].join("")
    });
    if (confirmed.endTurn) await endTurnIfCurrent(selfActor);
  }

  const name = activityName();
  if (/Настроить Око/i.test(name)) return configureEye();
  if (/Месть Самиэля/i.test(name)) return vengeance();
  if (!name && sourceItem.name?.includes("Око Возмездия")) return vengeance();
}).toString() + ")();";

function addUtilityActivity(itemData, name, offset) {
  const source = clone(itemData);
  const existingIds = new Set(Object.keys(source.system.activities ?? {}));
  source.system.activation = { type: "action", cost: 1, condition: "" };
  CONFIG.DND5E.activityTypes.utility.documentClass.createInitialActivity(source, { offset: offset });
  const activity = activityValues(source.system.activities).find(function(entry) { return !existingIds.has(entry._id); }) ?? activityValues(source.system.activities).at(-1);
  const oldId = activity._id;
  const id = foundry.utils.randomID(16);
  activity._id = id;
  activity.name = name;
  activity.img = IMG;
  activity.sort = offset;
  activity.uses = { spent: 0, max: "", recovery: [] };
  delete itemData.system.activities[oldId];
  itemData.system.activities[id] = activity;
}

function buildActivities(itemData) {
  itemData.system.activities = {};
  addUtilityActivity(itemData, "Настроить Око", 0);
  addUtilityActivity(itemData, "Месть Самиэля", 1);
}

