async function createOrUpdateJournal(folderId, item, dryRun) {
  const existing = game.journal.find(function(entry) { return entry.getFlag("ai-patcher", "bundleId") === BUNDLE_ID || entry.name === JOURNAL_NAME; });
  if (dryRun) return { action: existing ? "update" : "create", type: "JournalEntry", name: JOURNAL_NAME };
  const data = {
    name: JOURNAL_NAME,
    folder: folderId,
    flags: { "ai-patcher": { bundleId: BUNDLE_ID, role: "eye-of-vengeance-handout" } },
    pages: [{
      name: ITEM_NAME,
      type: "text",
      text: { format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML, content: journalContent(item) }
    }]
  };
  if (existing) return existing.update(data);
  return JournalEntry.create(data);
}

export default async function patch({ dryRun, log, bundle }) {
  IMG = asset(bundle, IMG_PATH);
  if (game.system.id !== "dnd5e") throw new Error("«Око Возмездия v1.0» создано для системы dnd5e.");
  const existing = game.items.find(function(item) { return item.getFlag("ai-patcher", "bundleId") === BUNDLE_ID || item.name === ITEM_NAME; });
  if (dryRun) {
    return {
      item: ITEM_NAME,
      action: existing ? "update" : "create",
      activities: ["Настроить Око", "Месть Самиэля"],
      image: IMG
    };
  }
  log("Создание или обновление предмета: " + ITEM_NAME);
  const itemFolder = await getOrCreateFolder(FOLDER_NAME, "Item");
  const journalFolder = await getOrCreateFolder(FOLDER_NAME, "JournalEntry");
  const itemData = buildItemData(itemFolder.id);
  const item = existing ? await existing.update(itemData) : await Item.create(itemData);
  if (!item) throw new Error("Не удалось создать Око Возмездия: Foundry не вернул документ Item.");
  await item.setFlag("ai-patcher", "bundleId", BUNDLE_ID);
  await createOrUpdateJournal(journalFolder.id, item, false);
  return {
    item: item.uuid,
    name: item.name,
    activities: activityValues(item.system.activities).map(function(activity) { return activity.name; }),
    image: item.img
  };
}
